(function(){'use strict';var calculatorState={currentStep:1,totalSteps:4,data:{postcode:'',propertyValue:0,agePrimary:0,agePartner:null,loanPurpose:'',hasPartner:!1},results:null};document.addEventListener('DOMContentLoaded',function(){initCalculator()});function initCalculator(){var calculator=document.querySelector('.m60-calculator-wrapper');if(!calculator){return}
initEventListeners();initFormatters()}
function initEventListeners(){var nextStep1=document.getElementById('m60-next-step-1');if(nextStep1){nextStep1.addEventListener('click',async()=>await handleStep1Next())}
var prevStep2=document.getElementById('m60-prev-step-2');var hasPartnerCheckbox=document.getElementById('m60-has-partner');var calculateBtn=document.getElementById('m60-calculate');if(prevStep2){prevStep2.addEventListener('click',function(){navigateToStep(1)})}
if(hasPartnerCheckbox){hasPartnerCheckbox.addEventListener('change',togglePartnerAge)}
if(calculateBtn){calculateBtn.addEventListener('click',handleCalculate)}
var recalculate=document.getElementById('m60-recalculate');var nextStep3=document.getElementById('m60-next-step-3');if(recalculate){recalculate.addEventListener('click',function(){navigateToStep(1)})}
if(nextStep3){nextStep3.addEventListener('click',function(){navigateToStep(4)})}
var prevStep4=document.getElementById('m60-prev-step-4');var leadForm=document.getElementById('m60-lead-form');if(prevStep4){prevStep4.addEventListener('click',function(){navigateToStep(3)})}
if(leadForm){leadForm.addEventListener('submit',handleLeadSubmit)}
var postcodeInput=document.getElementById('m60-postcode');if(postcodeInput){postcodeInput.addEventListener('blur',async()=>await validatePostcode());postcodeInput.addEventListener('input',function(){this.value=this.value.replace(/[^0-9]/g,'')})}}
function initFormatters(){var propertyValueInput=document.getElementById('m60-property-value');if(propertyValueInput){propertyValueInput.addEventListener('blur',function(){var value=parseFloat(this.value.replace(/[^0-9.]/g,''));if(!isNaN(value)){this.value=formatCurrency(value,!1)}});propertyValueInput.addEventListener('focus',function(){this.value=this.value.replace(/[^0-9]/g,'')})}}
async function handleStep1Next(){var postcode=document.getElementById('m60-postcode').value;var propertyValue=document.getElementById('m60-property-value').value;const isPostcodeValid=await validatePostcode();if(!isPostcodeValid){return}
var numericValue=parseFloat(propertyValue.replace(/[^0-9]/g,''));if(!numericValue||isNaN(numericValue)){showError('property-value-error','Please enter a valid property value');return}else{hideError('property-value-error')}
var minValue=m60CalcConfig.minPropertyValue;var maxValue=m60CalcConfig.maxPropertyValue;if(numericValue<minValue){showError('property-value-error','Property value must be at least '+formatCurrency(minValue));return}
if(numericValue>maxValue){showError('property-value-error','Property value cannot exceed '+formatCurrency(maxValue));return}
calculatorState.data.postcode=postcode;calculatorState.data.propertyValue=numericValue;navigateToStep(2)}
function togglePartnerAge(){var hasPartner=document.getElementById('m60-has-partner').checked;var partnerAgeGroup=document.getElementById('m60-partner-age-group');calculatorState.data.hasPartner=hasPartner;if(hasPartner){partnerAgeGroup.style.display='block'}else{partnerAgeGroup.style.display='none';document.getElementById('m60-age-partner').value='';calculatorState.data.agePartner=null}}
function handleCalculate(){var agePrimary=parseInt(document.getElementById('m60-age-primary').value);var agePartner=document.getElementById('m60-age-partner').value;var loanPurpose=document.getElementById('m60-loan-purpose').value;if(!agePrimary||isNaN(agePrimary)){showError('age-primary-error','Please enter your age');return}
var minAge=m60CalcConfig.minAge;if(agePrimary<minAge){showError('age-primary-error','Age must be at least '+minAge);return}
if(calculatorState.data.hasPartner&&agePartner){agePartner=parseInt(agePartner);if(isNaN(agePartner)||agePartner<minAge){showError('age-partner-error','Partner age must be at least '+minAge);return}}else{agePartner=null}
calculatorState.data.agePrimary=agePrimary;calculatorState.data.agePartner=agePartner;calculatorState.data.loanPurpose=loanPurpose;var calculateBtn=document.getElementById('m60-calculate');var spinner=calculateBtn.querySelector('.spinner-border');calculateBtn.disabled=!0;spinner.classList.remove('d-none');var data=new FormData();data.append('action','m60_calculate');data.append('nonce',m60CalcConfig.nonce);data.append('postcode',calculatorState.data.postcode);data.append('property_value',calculatorState.data.propertyValue);data.append('age_primary',calculatorState.data.agePrimary);if(calculatorState.data.agePartner){data.append('age_partner',calculatorState.data.agePartner)}
fetch(m60CalcConfig.ajaxUrl,{method:'POST',body:data}).then(function(response){return response.json()}).then(function(response){calculateBtn.disabled=!1;spinner.classList.add('d-none');if(response.success){calculatorState.results=response.data;displayResults(response.data);navigateToStep(3)}else{alert('Error calculating: '+(response.data.message||'Unknown error'))}}).catch(function(error){calculateBtn.disabled=!1;spinner.classList.add('d-none');alert('Error: '+error.message)})}
function displayResults(results){document.getElementById('m60-result-amount').textContent=formatCurrency(results.max_loan_amount);document.getElementById('m60-result-property-value').textContent=formatCurrency(results.property_value);var ageDisplay=results.age_primary;if(results.age_partner){ageDisplay+=' / '+results.age_partner}
document.getElementById('m60-result-age').textContent=ageDisplay;document.getElementById('m60-result-lvr').textContent=results.lvr_percentage+'%';var projectionTable=document.getElementById('m60-projection-table');projectionTable.innerHTML='';var years=[1,5,10,15,20];years.forEach(function(year){var balance=results.projections['year_'+year];if(balance){var row=document.createElement('tr');row.innerHTML='<td>Year '+year+'</td><td>'+formatCurrency(balance)+'</td>';projectionTable.appendChild(row)}})}
function handleLeadSubmit(e){e.preventDefault();var firstName=document.getElementById('m60-first-name').value;var lastName=document.getElementById('m60-last-name').value;var email=document.getElementById('m60-email').value;var phone=document.getElementById('m60-phone').value;var consent=document.getElementById('m60-consent').checked;if(!firstName||!lastName||!email){showFormError('Please fill in all required fields');return}
if(!consent){showFormError('Please agree to be contacted');return}
if(m60CalcConfig.requirePhone&&!phone){showFormError('Phone number is required');return}
var submitBtn=document.getElementById('m60-submit-lead');var spinner=submitBtn.querySelector('.spinner-border');submitBtn.disabled=!0;spinner.classList.remove('d-none');var data=new FormData();data.append('action','m60_submit_lead');data.append('nonce',m60CalcConfig.nonce);data.append('first_name',firstName);data.append('last_name',lastName);data.append('email',email);data.append('phone',phone);data.append('postcode',calculatorState.data.postcode);data.append('property_value',calculatorState.data.propertyValue);data.append('age_primary',calculatorState.data.agePrimary);if(calculatorState.data.agePartner){data.append('age_partner',calculatorState.data.agePartner)}
if(calculatorState.data.loanPurpose){data.append('loan_purpose',calculatorState.data.loanPurpose)}
if(calculatorState.results){data.append('estimated_amount',calculatorState.results.max_loan_amount)}
fetch(m60CalcConfig.ajaxUrl,{method:'POST',body:data}).then(function(response){return response.json()}).then(function(response){submitBtn.disabled=!1;spinner.classList.add('d-none');if(response.success){showFormSuccess(response.data.message||'Thank you! We\'ll be in touch soon.');document.getElementById('m60-lead-form').reset()}else{showFormError(response.data.message||'Error submitting form')}}).catch(function(error){submitBtn.disabled=!1;spinner.classList.add('d-none');showFormError('Error: '+error.message)})}
async function validatePostcode(){var postcodeInput=document.getElementById('m60-postcode');var postcode=postcodeInput.value;if(!postcode||postcode.length!==4){showError('postcode-error','Please enter a valid 4-digit postcode');postcodeInput.classList.add('is-invalid');return!1}
var data=new FormData();data.append('action','m60_validate_postcode');data.append('nonce',m60CalcConfig.nonce);data.append('postcode',postcode);try{const response=await fetch(m60CalcConfig.ajaxUrl,{method:'POST',body:data});const result=await response.json();if(!result.success){showError('postcode-error',result.data.message||'Error validating postcode');postcodeInput.classList.remove('is-valid');postcodeInput.classList.add('is-invalid');return!1}
if(result.data.valid){hideError('postcode-error');postcodeInput.classList.remove('is-invalid');postcodeInput.classList.add('is-valid');if(result.data.message){showError('postcode-error',result.data.message)}
return!0}
showError('postcode-error',result.data.message);postcodeInput.classList.add('is-invalid');return!1}catch(error){showError('postcode-error',error.message||'Error validating postcode');console.error("Validation failed",error);return!1}}
function navigateToStep(stepNumber){var steps=document.querySelectorAll('.m60-calc-step');steps.forEach(function(step){step.classList.remove('active')});var targetStep=document.getElementById('m60-step-'+stepNumber);if(targetStep){targetStep.classList.add('active')}
updateProgress(stepNumber);calculatorState.currentStep=stepNumber;var calculator=document.querySelector('.m60-calculator-wrapper');if(calculator){calculator.scrollIntoView({behavior:'smooth',block:'start'})}}
function updateProgress(currentStep){var progressSteps=document.querySelectorAll('.m60-progress-step');progressSteps.forEach(function(step,index){if(index+1<currentStep){step.classList.add('completed');step.classList.remove('active')}else if(index+1===currentStep){step.classList.add('active');step.classList.remove('completed')}else{step.classList.remove('active','completed')}});var progressBar=document.querySelector('.m60-progress-bar-fill');if(progressBar){var percentage=(currentStep/calculatorState.totalSteps)*100;progressBar.style.width=percentage+'%'}}
function formatCurrency(amount,showCents){if(typeof showCents==='undefined'){showCents=!1}
var formatted=Number(amount).toLocaleString('en-AU',{minimumFractionDigits:showCents?2:0,maximumFractionDigits:showCents?2:0});return'$'+formatted}
function showError(elementId,message){var errorElement=document.getElementById(elementId);if(errorElement){errorElement.textContent=message;errorElement.style.display='block'}}
function hideError(elementId){var errorElement=document.getElementById(elementId);if(errorElement){errorElement.textContent='';errorElement.style.display='none'}}
function showFormError(message){var errorDiv=document.getElementById('m60-form-error');var successDiv=document.getElementById('m60-form-success');if(successDiv){successDiv.classList.add('d-none')}
if(errorDiv){errorDiv.textContent=message;errorDiv.classList.remove('d-none')}}
function showFormSuccess(message){var errorDiv=document.getElementById('m60-form-error');var successDiv=document.getElementById('m60-form-success');if(errorDiv){errorDiv.classList.add('d-none')}
if(successDiv){successDiv.textContent=message;successDiv.classList.remove('d-none')}}})()